{
  "name": "opencode-choose-directory",
  "version": "0.1.12",
  "description": "Windows directory picker for the OpenCode V2 home screen.",
  "license": "MIT",
  "type": "module",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/huahai0202/opencode-choose-directory.git"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode2",
    "tui",
    "windows",
    "directory-picker"
  ],
  "engines": {
    "opencode": ">=2.0.0"
  },
  "exports": {
    ".": "./src/index.ts",
    "./tui": "./src/tui.tsx"
  },
  "files": [
    "src",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.0"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.17 <0.6.0",
    "@opentui/solid": ">=0.5.17 <0.6.0",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "@types/node": "^26.0.1",
    "typescript": "^6.0.3"
  }
}
